from collections import deque
def components(g,base):
    H,W=len(g),len(g[0]); seen=set(); comps=[]
    for r in range(H):
        for c in range(W):
            if g[r][c]!=base and (r,c) not in seen:
                q=deque([(r,c)]); seen.add((r,c)); comp=[]
                while q:
                    y,x=q.popleft(); comp.append((y,x))
                    for dy,dx in ((1,0),(-1,0),(0,1),(0,-1)):
                        ny,nx=y+dy,x+dx
                        if 0<=ny<H and 0<=nx<W and g[ny][nx]!=base and (ny,nx) not in seen:
                            seen.add((ny,nx)); q.append((ny,nx))
                comps.append(comp)
    return comps
